import type { Metadata } from "next";
import { Archivo } from "next/font/google";
import "./v1.css";

/**
 * Isolated shell for the v1 marketing rebuild.
 *
 * This route sits OUTSIDE the `(marketing)` group on purpose, so it inherits
 * none of the existing marketing chrome — no MarketingHeader, no footer, no
 * shared section primitives. The only thing it takes from the root layout is
 * the Geist/Geist Mono font variables and the base document.
 *
 * Type system, three roles:
 *   Archivo   — display voice. A wide, engineered grotesk; deliberately NOT
 *               Inter/Space Grotesk/Geist-at-display, which is the typographic
 *               tell that a page was generated rather than art-directed.
 *   Geist     — reading text. Shared with the portal, so the marketing site and
 *               the product feel like one company rather than two vendors.
 *   Geist Mono— machine values only (regions, latency, IPs, prices, counts).
 */
const v1Display = Archivo({
  subsets: ["latin"],
  weight: ["500", "600", "700"],
  variable: "--font-v1-display",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Nxeon — Infrastructure that deploys in 47 seconds",
  description:
    "Game servers, VPS, and web hosting on NVMe across Falkenstein and Singapore. Full root, dedicated IPv4, and a real control plane — deployed in 47 seconds.",
  robots: { index: false, follow: false },
};

export default function V1Layout({ children }: { children: React.ReactNode }) {
  return (
    <div className={`v1 ${v1Display.variable} min-h-screen`}>
      {children}
    </div>
  );

