import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

async function main() {
  const gp = await db.gamePlan.findMany({
    where: { active: true },
    select: { gameFamily: true, ramMB: true, cpuCores: true, diskGB: true, slots: true, priceCents: true, featured: true, sortOrder: true, termMonths: true },
    orderBy: [{ gameFamily: "asc" }, { priceCents: "asc" }],
  });
  const fams = new Map<string, typeof gp>();
  for (const p of gp) {
    const l = fams.get(p.gameFamily) ?? [];
    l.push(p);
    fams.set(p.gameFamily, l);
  }
  console.log("active gamePlan rows:", gp.length, "families:", fams.size);
  for (const [f, list] of fams) {
    console.log(f, "->", list.length, "tiers; cheapest:", JSON.stringify(list[0]));
  }
  const mods = await db.gameMod.count({ where: { active: true, upstreamOk: true } });
  const modFams = await db.gameMod.findMany({ where: { active: true, upstreamOk: true }, distinct: ["gameFamily"], select: { gameFamily: true } });
  console.log("mods:", mods, "modFams:", modFams.length, modFams.map(m => m.gameFamily).join(","));
  const plans = await db.plan.findMany({ where: { active: true }, select: { slug: true, name: true, priceCents: true, ramMB: true, cpuCores: true, diskGB: true }, orderBy: { priceCents: "asc" } });
  console.log("VPS plans:", JSON.stringify(plans, null, 1));
  const nodes = await db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } });
  console.log("nodes:", JSON.stringify(nodes));
  await db.$disconnect();
}
main();

