import fs from "node:fs";
import { PrismaClient } from "@prisma/client";
import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "/opt/nxeon/lib/games";
const db = new PrismaClient();
const DIR = "/opt/nxeon/public/games/art";

async function main() {
  const rows = await db.gamePlan.findMany({ where: { active: true }, select: { gameFamily: true } });
  const fams = [...new Set(rows.map((r) => r.gameFamily))] as GameFamily[];
  const missing: string[] = [];
  for (const f of fams.sort()) {
    const a = GAME_ART_SLUG[f];
    const p = a?.poster ? fs.existsSync(`${DIR}/${a.poster}_poster.jpg`) : false;
    const h = a?.hero ? fs.existsSync(`${DIR}/${a.hero}_hero.jpg`) : false;
    const lg = a?.poster ? fs.existsSync(`${DIR}/${a.poster}_logo.png`) : false;
    if (!p || !h) missing.push(`${f} poster=${p} hero=${h}`);
    console.log(`${f.padEnd(18)} ${String(GAME_DISPLAY[f].name).padEnd(30)} poster=${p ? "Y" : "n"} hero=${h ? "Y" : "n"} logo=${lg ? "Y" : "n"}`);
  }
  console.log("\nMISSING:", missing.length ? missing : "none");
  await db.$disconnect();
}
main();

