import sharp from "sharp";
import fs from "node:fs";

const DIR = "/opt/nxeon/public/games/art";

function rgbToHsl(r: number, g: number, b: number) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const l = (max + min) / 2;
  let h = 0, s = 0;
  const d = max - min;
  if (d !== 0) {
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) h = ((g - b) / d + (g < b ? 6 : 0));
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
  }
  return { h, s, l };
}
function hslToHex(h: number, s: number, l: number) {
  const c = (n: number) => {
    const k = (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    return Math.round(255 * v).toString(16).padStart(2, "0");
  };
  return `#${c(0)}${c(8)}${c(4)}`;
}

async function tint(file: string) {
  const { data, info } = await sharp(file).resize(40, 54, { fit: "cover" }).raw().toBuffer({ resolveWithObject: true });
  const ch = info.channels;
  const buckets = new Map<number, { w: number; h: number; s: number; l: number }>();
  for (let i = 0; i < data.length; i += ch) {
    const { h, s, l } = rgbToHsl(data[i], data[i + 1], data[i + 2]);
    if (l < 0.12 || l > 0.9) continue;
    if (s < 0.14) continue;
    const b = Math.floor(h / 18);
    const w = s * s * (1 - Math.abs(l - 0.5) * 1.2);
    const cur = buckets.get(b) ?? { w: 0, h: 0, s: 0, l: 0 };
    cur.w += w; cur.h += h * w; cur.s += s * w; cur.l += l * w;
    buckets.set(b, cur);
  }
  let best: { w: number; h: number; s: number; l: number } | null = null;
  for (const v of buckets.values()) if (!best || v.w > best.w) best = v;
  if (!best || best.w === 0) return { hex: "#6b6b7a", h: 240 };
  const h = best.h / best.w, s = best.s / best.w, l = best.l / best.w;
  const S = Math.min(0.92, Math.max(0.58, s * 1.25));
  const L = Math.min(0.64, Math.max(0.5, l * 1.1));
  return { hex: hslToHex(h, S, L), h: Math.round(h) };
}

async function main() {
  const posters = fs.readdirSync(DIR).filter((f) => f.endsWith("_poster.jpg"));
  const t0 = Date.now();
  const out: string[] = [];
  for (const p of posters) {
    const r = await tint(`${DIR}/${p}`);
    out.push(`${p.replace("_poster.jpg", "").padEnd(26)} ${r.hex}  h=${r.h}`);
  }
  console.log(out.join("\n"));
  console.log(`\n${posters.length} posters in ${Date.now() - t0}ms  (${Math.round((Date.now() - t0) / posters.length)}ms each)`);
}
main();

