/* ===========================================================================
   Nxeon marketing v1 — a self-contained design layer.

   Scoped entirely under `.v1` so it shares nothing with the existing
   marketing CSS and cannot leak into (or be overridden by) app/globals.css.
   Every token below is declared here, not inherited.

   The palette is derived from the real Aurora concepts on the project board
   (board card "Aurora UI/UX Overhaul" + "aurora borelias"), not invented:
   a blue-black ground, a blue-tinted text ladder rather than neutral grey,
   hairline rims in blue rather than white-alpha, and the aurora spectrum
   (teal -> cyan -> blue -> violet -> magenta) used as LIGHT, never as a
   decorative fill. Semantic status colour is deliberately kept outside that
   spectrum so "healthy" never reads as "brand".
   =========================================================================== */

.v1 {
  /* ---- ground ---------------------------------------------------------- */
  --v1-void: #03050d;
  --v1-bg: #060a16;
  --v1-surface: #0a1020;
  --v1-raised: #0e1526;
  --v1-well: #050810;

  /* ---- rims (blue-tinted hairlines, never white-alpha) ------------------ */
  --v1-rim: rgba(84, 132, 214, 0.14);
  --v1-rim-hi: rgba(120, 172, 255, 0.28);
  --v1-rim-glow: rgba(47, 126, 239, 0.45);

  /* ---- aurora spectrum (light, not fill) -------------------------------- */
  --v1-a-mint: #3fe0b0;
  --v1-a-cyan: #14c5e4;
  --v1-a-blue: #2f7eef;
  --v1-a-violet: #8c3ae9;
  --v1-a-magenta: #d623e1;

  /* ---- type ladder (blue-tinted, matching the portal's intent) ---------- */
  --v1-tx: #f4f8ff;
  --v1-tx-body: #c0d0ec;
  --v1-tx-mute: #8ba1c6;
