/* ===========================================================================
   v8 "Arcade" — key-art helpers + per-title colour extraction.

   SERVER ONLY. This module touches `fs` and (lazily) `sharp`; never import it
   from a "use client" file. It deliberately has NO "use client" directive and
   exports plain functions/values, not components — see the sibling icons.tsx
   header for why that distinction matters in this codebase.

   Why colour is SAMPLED rather than listed: the v8 concept has no global brand
   accent at all. Every saturated colour on the page is pulled out of the real
   key art sitting in public/games/art, so a title's card glows in its own
   game's colour. A hand-written table of hexes would be a second copy of that
   art's palette, drifting the first time a poster is re-sourced (which has
   already happened twice in this repo — see GAME_ART_SLUG's comments).

   Cost, measured on the real files: 5ms per poster, 220ms for all 44. The
   results are memoised per process, so only the first render of the route pays
   anything at all.
   =========================================================================== */
import fs from "node:fs";
import path from "node:path";
import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";

const ART_DIR = path.join(process.cwd(), "public", "games", "art");

/**
 * The art directory's real contents, read once. `null` means the read itself
 * failed, which is treated as "unknown" rather than "absent": the helpers below
 * then hand back the conventional path optimistically and let the browser's own
 * 404 handling take over, because refusing to render any art at all would be a
 * far worse failure than one broken <img>.
 *
 * Several files that LOOK available are 0 bytes (public/logos/{caddy,steam,
 * counterstrike,wine}.svg) — this page references none of them. Everything
 * under public/games/art was size-checked before being used here.
 */
let dirCache: Set<string> | null | undefined;
function artFiles(): Set<string> | null {
  if (dirCache === undefined) {
    try {
      dirCache = new Set(fs.readdirSync(ART_DIR));
    } catch {
      dirCache = null;
    }
  }
  return dirCache;
}

function pick(file: string): string | null {
  const set = artFiles();
  if (set && !set.has(file)) return null;
  return `/games/art/${file}`;
}

/** Portrait key art, 300x450. Present for every family with an active plan. */
export function posterFor(fam: GameFamily): string | null {
  const slug = GAME_ART_SLUG[fam]?.poster;
  return slug ? pick(`${slug}_poster.jpg`) : null;
}

/** 16:9 key art, 1200x675. Absent for kf2, so callers must handle null. */
export function heroFor(fam: GameFamily): string | null {
  const slug = GAME_ART_SLUG[fam]?.hero;
  return slug ? pick(`${slug}_hero.jpg`) : null;
}

/**
 * The title's own logotype, 640x360 with alpha. Present for 28 of the 42
 * families; where it is missing the title is set in the display face instead,
 * which is a deliberate second treatment rather than a fallback that looks
 * broken.
 */
export function logoFor(fam: GameFamily): string | null {
  const slug = GAME_ART_SLUG[fam]?.poster ?? GAME_ART_SLUG[fam]?.hero;
  return slug ? pick(`${slug}_logo.png`) : null;
}

export type Tint = {
  /** The card's glow/rim colour: the poster's dominant saturated hue. */
  glow: string;
  /** Same hue, pulled toward paper — legible for small type on the dark ground. */
  ink: string;
};

/* Neutral graphite. Used when a family has no poster, or when sharp is
   unavailable — the page then reads as an intentionally monochrome shelf rather
   than losing its rim treatment entirely. */
const NEUTRAL: Tint = { glow: "#83839a", ink: "#c3c3cf" };

const tintCache = new Map<string, Tint>();

function rgbToHsl(r: number, g: number, b: number) {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d === 0) return { h: 0, s: 0, l };
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h: number;
  if (max === r) h = (g - b) / d + (g < b ? 6 : 0);
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return { h: h * 60, s, l };
}

function hslToHex(h: number, s: number, l: number) {
  const chan = (n: number) => {
    const k = (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    return Math.round(255 * v)
      .toString(16)
      .padStart(2, "0");
  };
  return `#${chan(0)}${chan(8)}${chan(4)}`;
}

/**
 * The dominant *saturated* hue of a title's poster.
 *
 * Not a plain average — averaging key art returns mud every time, because most
 * posters are mostly dark. Instead: downsample to 40x54, throw away the near
 * black, the near white and the near grey, bucket what is left by hue in 20
 * buckets, weight each pixel by saturation-squared and by how close it sits to
 * mid lightness, then take the heaviest bucket's weighted mean.
 *
 * The final clamp is the art direction: S into 0.46-0.74 and L into 0.55-0.68
 * so the result is rich rather than fluorescent. Unclamped, several posters
 * return things like #f51b0a, which is a hazard-light, not a glow.
 */
export async function tintFor(fam: GameFamily): Promise<Tint> {
  const cached = tintCache.get(fam);
  if (cached) return cached;

  const rel = posterFor(fam);
  if (!rel) {
    tintCache.set(fam, NEUTRAL);
    return NEUTRAL;
  }

  let out = NEUTRAL;
  try {
    const sharp = (await import("sharp")).default;
    const { data, info } = await sharp(path.join(process.cwd(), "public", rel.replace(/^\//, "")))
      .resize(40, 54, { fit: "cover" })
      .raw()
      .toBuffer({ resolveWithObject: true });

    const buckets = new Map<number, { w: number; h: number; s: number; l: number }>();
    for (let i = 0; i < data.length; i += info.channels) {
      const { h, s, l } = rgbToHsl(data[i], data[i + 1], data[i + 2]);
      if (l < 0.12 || l > 0.9 || s < 0.14) continue;
      const key = Math.floor(h / 18);
      const w = s * s * (1 - Math.abs(l - 0.5) * 1.2);
      const cur = buckets.get(key) ?? { w: 0, h: 0, s: 0, l: 0 };
      cur.w += w;
      cur.h += h * w;
      cur.s += s * w;
      cur.l += l * w;
      buckets.set(key, cur);
    }

    let best: { w: number; h: number; s: number; l: number } | null = null;
    for (const v of buckets.values()) if (!best || v.w > best.w) best = v;

    if (best && best.w > 0) {
      const h = best.h / best.w;
      const s = best.s / best.w;
      const l = best.l / best.w;
      out = {
        glow: hslToHex(h, Math.min(0.74, Math.max(0.46, s * 1.05)), Math.min(0.68, Math.max(0.55, l * 1.15))),
        ink: hslToHex(h, Math.min(0.5, Math.max(0.3, s * 0.72)), 0.8),
      };
    }
  } catch {
    /* sharp missing or the file unreadable — the neutral shelf is a fine page. */
  }

  tintCache.set(fam, out);
  return out;
}

/* ===========================================================================
   v8 "Arcade" — the shape of everything the server hands the client islands.

   Plain module, no "use client", no components — so both the Server Component
   page and the client islands can import from it safely.

   Every field here is READ FROM THE DATABASE OR FROM DISK by app/newwebsitev8/
   page.tsx. Nothing on this page is a literal: the title count, the tier
   counts, the entry prices, the slot counts, the region list and the mod
   catalogue size are all queried per request (the route is force-dynamic), and
   the tint is sampled out of the real poster. The only fixed strings in the
   copy are the two pre-approved claims ("99.99% network", "online in 47
   seconds").
   =========================================================================== */

/** One GamePlan row, reduced to what the page shows. */
export type Tier = {
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  /** GamePlan.slots is nullable — a few families genuinely have no slot cap. */
  slots: number | null;
  priceCents: number;
  termMonths: number;
};

export type Title = {
  /** GameFamily id, e.g. "projectzomboid". Used only as a React key / filter. */
  fam: string;
  /** GAME_DISPLAY name — the canonical capitalisation, never the raw slug. */
  name: string;
  genres: string[];
  /**
   * The title's own landing page, or /game-servers for the one active family
   * (stationeers) that has no dedicated route — linking it to a
   * <slug>-server-hosting URL would 404.
   */
  href: string;
  poster: string | null;
  hero: string | null;
  logo: string | null;
  /** Sampled from `poster`. See art.ts. */
  tint: string;
  tintInk: string;
  /** How many active GamePlan tiers this family has. */
  tierCount: number;
  /** The cheapest active tier. */
  from: Tier;
};

export type RegionPlate = {
  key: string;
  /** CUSTOMER_REGION_LABELS — "Singapore" / "Germany", never the DC code. */
  label: string;
  /** regionsFrom()'s `area` — "Asia" / "Europe". */
  area: string;
  /**
   * regionsFrom()'s nominal `ms`. INDICATIVE FOR THE REGION — the platform
   * never probes a visitor's connection, and lib/nx/catalog.ts says so in its
   * own comment. Must always be rendered with that caveat attached.
   */
  nominalMs: number;
};

/* ===========================================================================
   v8 "Arcade" — shared line icons.

   NO "use client" HERE, DELIBERATELY, and each icon is its own named export.

   Known trap in this codebase: exporting an OBJECT of components from a
   "use client" module and reading properties off it in a Server Component
   (`export const Icon = { bolt }` then `<Icon.bolt />` on the server) resolves
   to `undefined` through the client reference, and React throws "Element type
   is invalid". Plain module + individual named exports is the shape that works
   from both sides of the boundary.

   All icons inherit `currentColor` and are 1.5px-stroked at 24px, so they sit
   on the same optical weight as DM Mono's stems.
   =========================================================================== */
type P = { className?: string; size?: number };

const base = (size: number) => ({
  width: size,
  height: size,
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 1.5,
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
  "aria-hidden": true,
  focusable: false as const,
});

export function IconArrow({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M4 12h15" />
      <path d="M13 6l6 6-6 6" />
    </svg>
  );
}

export function IconGrip({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M9 5v14M15 5v14" />
    </svg>
  );
}

export function IconBolt({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M13 2L5 14h6l-1 8 8-12h-6l1-8z" />
    </svg>
  );
}

export function IconTerminal({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <rect x="2.5" y="4" width="19" height="16" rx="2.5" />
      <path d="M7 10l2.5 2L7 14M12.5 15h4" />
    </svg>
  );
}

export function IconDisk({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <ellipse cx="12" cy="6" rx="8" ry="3" />
      <path d="M4 6v12c0 1.7 3.6 3 8 3s8-1.3 8-3V6" />
      <path d="M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3" />
    </svg>
  );
}

export function IconPin({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M12 21s7-5.7 7-11a7 7 0 10-14 0c0 5.3 7 11 7 11z" />
      <circle cx="12" cy="10" r="2.5" />
    </svg>
  );
}

export function IconPuzzle({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M10 3.5a2 2 0 014 0V5h2.5A1.5 1.5 0 0118 6.5V10h1.5a2 2 0 010 4H18v3.5A1.5 1.5 0 0116.5 19H13v-1.5a2 2 0 10-4 0V19H5.5A1.5 1.5 0 014 17.5V14h1.5a2 2 0 000-4H4V6.5A1.5 1.5 0 015.5 5H10V3.5z" />
    </svg>
  );
}

export function IconShield({ className, size = 18 }: P) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M12 3l7 3v5.5c0 4.6-3 8-7 9.5-4-1.5-7-4.9-7-9.5V6l7-3z" />
      <path d="M9 12l2 2 4-4" />
    </svg>
  );
}

"use client";

/* ===========================================================================
   v8 "Arcade" — pointer-tracked tilt + sheen.

   The one piece of interaction the whole concept leans on: a poster should feel
   like a physical object you are holding up to a light. Two things make that
   read as weight rather than as a CSS trick —

   1. The card tracks the pointer with an almost-zero transition while the
      pointer is down/over (so it feels attached), and settles back with a
      SPRING curve that slightly overshoots when the pointer leaves (so it feels
      sprung). Two different easings, swapped by a class.
   2. The sheen is a real specular highlight positioned at the pointer, not a
      fixed diagonal gradient — so it slides across the art as the card turns.

   Everything is written to CSS custom properties on the element, never to React
   state: a pointermove at 120Hz through a React re-render would drop frames on
   a 42-card grid. rAF-coalesced so several moves in one frame cost one write.

   Respects prefers-reduced-motion by doing nothing at all (the CSS keeps the
   card flat and the sheen off), and is a no-op for coarse pointers, where there
   is no hover to track and the rack's tap-to-reveal is the interaction instead.
   =========================================================================== */
import { useCallback, useEffect, useRef } from "react";

const MAX_DEG = 7;

export function useTilt<T extends HTMLElement = HTMLDivElement>() {
  const ref = useRef<T | null>(null);
  const frame = useRef(0);
  const pending = useRef<{ x: number; y: number } | null>(null);
  const live = useRef(false);

  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const flush = useCallback(() => {
    frame.current = 0;
    const el = ref.current;
    const p = pending.current;
    if (!el || !p) return;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // -0.5..0.5 from the card's centre.
    const nx = (p.x - r.left) / r.width - 0.5;
    const ny = (p.y - r.top) / r.height - 0.5;
    el.style.setProperty("--ry", `${(nx * MAX_DEG * 2).toFixed(2)}deg`);
    el.style.setProperty("--rx", `${(-ny * MAX_DEG * 2).toFixed(2)}deg`);
    el.style.setProperty("--mx", `${((nx + 0.5) * 100).toFixed(1)}%`);
    el.style.setProperty("--my", `${((ny + 0.5) * 100).toFixed(1)}%`);
  }, []);

  const onPointerMove = useCallback(
    (e: React.PointerEvent<T>) => {
      if (e.pointerType === "touch") return;
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      const el = ref.current;
      if (!el) return;
      if (!live.current) {
        live.current = true;
        // Short, near-linear transition while tracking: the card feels attached
        // to the pointer instead of lagging a third of a second behind it.
        el.classList.add("v8-live");
      }
      pending.current = { x: e.clientX, y: e.clientY };
      if (!frame.current) frame.current = requestAnimationFrame(flush);
    },
    [flush],
  );

  const onPointerLeave = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    live.current = false;
    pending.current = null;
    if (frame.current) {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    }
    // Dropping v8-live hands the element back to the spring curve, which is
    // what gives the release its overshoot.
    el.classList.remove("v8-live");
    el.style.removeProperty("--rx");
    el.style.removeProperty("--ry");
  }, []);

  return { ref, onPointerMove, onPointerLeave };
}

