"use client";

/* ===========================================================================
   v8 "Arcade" — THE MARQUEE (hero).

   A premium-storefront shelf, not a SaaS hero: the selected title's real 16:9
   key art fills the whole viewport behind the masthead, and a draggable rail of
   portrait posters runs along the bottom edge. Picking a poster swaps the
   backdrop, the title plate and the price — which is the moment this concept
   lives or dies on, so it is built to feel physical:

   - posters tilt under the pointer with a specular sheen (useTilt)
   - the rail is a NATIVE overflow scroller, so touch, trackpad and keyboard all
     work with zero JS; mouse drag-to-scroll is layered on top as an enhancement
   - the active poster rises out of the rail and takes its own sampled tint

   DRAG THRESHOLD IS 40px ON PURPOSE. A threshold under ~8px has been a real bug
   in this repo: ordinary clicks travel a pixel or two between pointerdown and
   pointerup, get classified as drags, and the click is swallowed. Nothing calls
   setPointerCapture until the pointer has genuinely crossed 40px either, since
   capturing early is what redirects the click away from the poster.

   Backdrop images are mounted LAZILY AND KEPT: only the first title's hero is
   fetched on load, hovering a poster pre-fetches its hero, and anything already
   seen stays mounted so going back is instant. Stacking all fourteen up front
   would be ~1.5MB nobody asked for; fetching on click alone would make every
   switch flash.
   =========================================================================== */
import Image from "next/image";
import Link from "next/link";
import { useCallback, useRef, useState } from "react";
import { money } from "@/lib/nx/catalog";
import { useTilt } from "./tilt";
import { IconArrow, IconBolt, IconGrip } from "./icons";
import type { Title } from "./types";

/** px the pointer must travel before the rail treats the gesture as a drag. */
const DRAG_THRESHOLD = 40;
/** ms after a drag ends during which a click is treated as drag fallout. */
const CLICK_SWALLOW_MS = 150;

function Spec({ label, value }: { label: string; value: string }) {
  return (
    <div className="v8-spec">
      <span className="v8-spec-k">{label}</span>
      <span className="v8-spec-v">{value}</span>
    </div>
  );
}

function RailPoster({
  title,
  active,
  onPick,
  onPeek,
}: {
  title: Title;
  active: boolean;
  onPick: () => void;
  onPeek: () => void;
}) {
  const tilt = useTilt<HTMLButtonElement>();
  return (
    <button
      type="button"
      ref={tilt.ref}
      onPointerMove={tilt.onPointerMove}
      onPointerLeave={tilt.onPointerLeave}
      onPointerEnter={onPeek}
      onFocus={onPeek}
      onClick={onPick}
      aria-pressed={active}
      className={`v8-rail-card v8-tilt ${active ? "is-active" : ""}`}
      style={{ ["--tint" as string]: title.tint }}
    >
      <span className="v8-rail-shot">
        {title.poster ? (
          <Image
            src={title.poster}
            alt=""
            width={300}
            height={450}
            quality={74}
            sizes="180px"
            draggable={false}
          />
        ) : null}
        <span className="v8-sheen" aria-hidden />
      </span>
      <span className="v8-rail-name">{title.name}</span>
      <span className="v8-rail-price">{money(title.from.priceCents)}</span>
    </button>
  );
}

export default function Marquee({
  features,
  familyCount,
  regionLabels,
  entryPrice,
}: {
  features: Title[];
  familyCount: number;
  regionLabels: string[];
  entryPrice: string;
}) {
  const [active, setActive] = useState(0);
  const [seen, setSeen] = useState<Set<number>>(() => new Set([0]));
  const railRef = useRef<HTMLDivElement | null>(null);
  const drag = useRef({ down: false, moved: false, startX: 0, startScroll: 0, id: -1, endedAt: 0 });

  const peek = useCallback((i: number) => {
    setSeen((prev) => (prev.has(i) ? prev : new Set(prev).add(i)));
  }, []);

  const pick = useCallback(
    (i: number, node: HTMLElement | null) => {
      // A click that arrives right after a drag is that drag's fallout, not an
      // intent to pick. Time-based rather than a flag so a stale flag can never
      // swallow a real, later click.
      if (performance.now() - drag.current.endedAt < CLICK_SWALLOW_MS) return;
      setActive(i);
      peek(i);
      node?.scrollIntoView({ inline: "center", block: "nearest" });
    },
    [peek],
  );

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    // Touch and pen keep the browser's own momentum scrolling — hijacking it
    // with scrollLeft writes is strictly worse than the native behaviour.
    if (e.pointerType !== "mouse" || e.button !== 0) return;
    const el = railRef.current;
    if (!el) return;
    drag.current = {
      down: true,
      moved: false,
      startX: e.clientX,
      startScroll: el.scrollLeft,
      id: e.pointerId,
      endedAt: 0,
    };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d.down) return;
    const el = railRef.current;
    if (!el) return;
    const dx = e.clientX - d.startX;
    if (!d.moved) {
      if (Math.abs(dx) < DRAG_THRESHOLD) return;
      d.moved = true;
      // Only now — capturing before the threshold is crossed is what steals
      // ordinary clicks from the posters.
      try {
        el.setPointerCapture(d.id);
      } catch {
        /* capture is an enhancement; the drag still tracks without it */
      }
      el.classList.add("v8-dragging");
    }
    el.scrollLeft = d.startScroll - dx;
  };

  const endDrag = () => {
    const d = drag.current;
    const el = railRef.current;
    if (d.moved) {
      d.endedAt = performance.now();
      if (el) {
        try {
          el.releasePointerCapture(d.id);
        } catch {
          /* already released */
        }
        el.classList.remove("v8-dragging");
      }
    }
    d.down = false;
  };

  const hero = features[active];
  const slots = hero.from.slots;
  const term = hero.from.termMonths === 1 ? "/mo" : ` / ${hero.from.termMonths} mo`;

  return (
    <section className="v8-mq" style={{ ["--tint" as string]: hero.tint, ["--tint-ink" as string]: hero.tintInk }}>
      {/* ---- backdrop: the selected title's real key art ------------------ */}
      <div className="v8-mq-art" aria-hidden>
        {features.map((t, i) =>
          seen.has(i) && t.hero ? (
            <Image
              key={t.fam}
              src={t.hero}
              alt=""
              fill
              quality={72}
              sizes="100vw"
              priority={i === 0}
              className={`v8-mq-shot ${i === active ? "is-on" : ""}`}
            />
          ) : null,
        )}
        <div className="v8-mq-scrim" />
        <div className="v8-mq-bloom" />
      </div>

      {/* ---- top bar ------------------------------------------------------ */}
      <header className="v8-top">
        <Link href="/" className="v8-top-brand" aria-label="Nxeon home">
          {/* The real brand wordmark. Never re-drawn, never re-coloured. */}
          <Image src="/logo.png" alt="Nxeon" width={496} height={85} priority />
        </Link>
        <nav className="v8-top-nav" aria-label="Primary">
          <Link href="/game-servers">Game servers</Link>
          <Link href="/mods">Mods</Link>
          <Link href="/vps">VPS</Link>
          <Link href="/pricing">Pricing</Link>
        </nav>
        <div className="v8-top-act">
          <Link href="/login" className="v8-top-login">
            Sign in
          </Link>
          <Link href="/dashboard/deploy" className="v8-btn v8-btn-paper">
            Deploy a server
            <IconArrow />
          </Link>
        </div>
      </header>

      {/* ---- masthead + feature plate ------------------------------------- */}
      <div className="v8-mq-body">
        <div className="v8-mast">
          <p className="v8-kicker">
            Game server hosting
            <span className="v8-kicker-dot" />
            {regionLabels.join(" & ")}
          </p>
          <h1 className="v8-mast-h">
            <span className="v8-mast-l1">
              <em>{familyCount}</em> worlds.
            </span>
            <span className="v8-mast-l2">Online in 47 seconds.</span>
          </h1>
          <p className="v8-deck">
            Every title on this shelf gets its own machine on NVMe — sized from a real plan, on a 99.99%
            network, with the console and the file tree in your hands from the first minute. From{" "}
            <strong>{entryPrice}</strong> a month.
          </p>
          <div className="v8-mast-act">
            <Link href="/dashboard/deploy" className="v8-btn v8-btn-paper v8-btn-lg">
              <IconBolt />
              Start a server
            </Link>
            <a href="#rack" className="v8-btn v8-btn-ghost v8-btn-lg">
              See all {familyCount} titles
            </a>
          </div>
        </div>

        {/* The plate is the selected title's REAL cheapest active tier. */}
        <aside className="v8-plate" aria-live="polite">
          <div className="v8-plate-head">
            {hero.logo ? (
              <Image
                src={hero.logo}
                alt={`${hero.name} logo`}
                width={640}
                height={360}
                quality={82}
                sizes="320px"
                className="v8-plate-logo"
              />
            ) : (
              <span className="v8-plate-word">{hero.name}</span>
            )}
          </div>
          <ul className="v8-chips">
            {hero.genres.map((g) => (
              <li key={g}>{g}</li>
            ))}
            <li className="v8-chip-tier">
              {hero.tierCount} {hero.tierCount === 1 ? "tier" : "tiers"}
            </li>
          </ul>
          <div className="v8-plate-specs">
            <Spec label="RAM" value={`${hero.from.ramMB / 1024} GB`} />
            <Spec label="vCPU" value={`${hero.from.cpuCores}`} />
            <Spec label="NVMe" value={`${hero.from.diskGB} GB`} />
            <Spec label="Slots" value={slots === null ? "uncapped" : `${slots}`} />
          </div>
          <div className="v8-plate-foot">
            <p className="v8-price">
              <span className="v8-price-k">from</span>
              <span className="v8-price-v">{money(hero.from.priceCents)}</span>
              <span className="v8-price-t">{term}</span>
            </p>
            <Link href={hero.href} className="v8-btn v8-btn-tint">
              {hero.name} plans
              <IconArrow />
            </Link>
          </div>
        </aside>
      </div>

      {/* ---- the rail ------------------------------------------------------ */}
      <div className="v8-rail-wrap">
        <p className="v8-rail-label">
          <IconGrip size={14} />
          Featured shelf — drag, or pick a title
        </p>
        <div
          ref={railRef}
          className="v8-rail"
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          role="group"
          aria-label="Featured titles"
        >
          {features.map((t, i) => (
            <RailPoster
              key={t.fam}
              title={t}
              active={i === active}
              onPeek={() => peek(i)}
              onPick={() => pick(i, railRef.current?.children[i] as HTMLElement | undefined ?? null)}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

/* ===========================================================================
   v8 "Arcade" — THE RACK.

   The maximalist move of the concept: rather than six hand-picked hero cards
   (which is what every hosting page does), this shows EVERY title that has an
   active GamePlan, as a dense wall of real key art. The catalogue itself is the
   flex, so it is shown at full size.

   Each poster is a physical object: it tilts under the pointer with a specular
   sheen, lifts on a spring, takes a rim and a floor-glow in its OWN sampled
   colour, and reveals that title's real cheapest tier — RAM, cores, NVMe,
   slots, price — from the database.

   Two accessibility/robustness details worth keeping:

   - The whole card is made clickable by ONE stretched <a>, not by nesting links
     inside links. The revealed panel is aria-hidden and the link carries the
     full accessible name, so the reveal is also what `:focus-within` triggers —
     keyboard users see exactly what pointer users see.
   - Under `(hover: none)` the panel is NOT hidden behind a hover that cannot
     happen: it renders open and static. Nothing on this page is ever parked at
     opacity 0 waiting for an observer, on any input type.
   =========================================================================== */
import Image from "next/image";
import Link from "next/link";
import { useMemo, useState } from "react";
import { money } from "@/lib/nx/catalog";
import { useTilt } from "./tilt";
import { IconArrow } from "./icons";
import type { Title } from "./types";

const ALL = "All titles";

function RackCard({ t }: { t: Title }) {
  const tilt = useTilt<HTMLElement>();
  const slots = t.from.slots;
  const price = money(t.from.priceCents);
  return (
    <article
      ref={tilt.ref}
      onPointerMove={tilt.onPointerMove}
      onPointerLeave={tilt.onPointerLeave}
      className="v8-rk-card v8-tilt"
      style={{ ["--tint" as string]: t.tint, ["--tint-ink" as string]: t.tintInk }}
    >
      <div className="v8-rk-shot">
        {t.poster ? (
          <Image src={t.poster} alt={`${t.name} key art`} width={300} height={450} quality={74} sizes="240px" />
        ) : (
          <div className="v8-rk-noart" aria-hidden />
        )}
        <span className="v8-sheen" aria-hidden />
        <span className="v8-rk-rim" aria-hidden />
      </div>

      <div className="v8-rk-plate">
        <h3 className="v8-rk-name">{t.name}</h3>
        <p className="v8-rk-from">
          <span>from</span> {price}
        </p>
      </div>

      <div className="v8-rk-panel" aria-hidden>
        <dl className="v8-rk-specs">
          <div>
            <dt>RAM</dt>
            <dd>{t.from.ramMB / 1024} GB</dd>
          </div>
          <div>
            <dt>vCPU</dt>
            <dd>{t.from.cpuCores}</dd>
          </div>
          <div>
            <dt>NVMe</dt>
            <dd>{t.from.diskGB} GB</dd>
          </div>
          <div>
            <dt>Slots</dt>
            <dd>{slots === null ? "—" : slots}</dd>
          </div>
        </dl>
        <p className="v8-rk-go">
          {t.tierCount} {t.tierCount === 1 ? "tier" : "tiers"}
          <IconArrow size={15} />
        </p>
      </div>

      {/* One stretched link for the whole card — no nested anchors. */}
      <Link href={t.href} className="v8-stretch">
        <span className="v8-sr">
          {t.name} server hosting, from {price} a month
        </span>
      </Link>
    </article>
  );
}

export default function Rack({
  titles,
  genres,
  tierCount,
  entryPrice,
}: {
  titles: Title[];
  genres: string[];
  tierCount: number;
  entryPrice: string;
}) {
  const [filter, setFilter] = useState<string>(ALL);

  const counts = useMemo(() => {
    const m = new Map<string, number>([[ALL, titles.length]]);
    for (const g of genres) m.set(g, titles.filter((t) => t.genres.includes(g)).length);
    return m;
  }, [titles, genres]);

  const shown = useMemo(
    () => (filter === ALL ? titles : titles.filter((t) => t.genres.includes(filter))),
    [titles, filter],
  );

  return (
    <section className="v8-rack" id="rack">
      <div className="v8-rack-head">
        <div>
          <p className="v8-kicker">The rack</p>
          <h2 className="v8-h2">
            Every title we
            <br />
            actually have plans for.
          </h2>
        </div>
        <div className="v8-rack-meta">
          <p>
            {titles.length} titles, {tierCount} plan tiers, priced from {entryPrice} a month. Pull a poster off the
            shelf to see what its entry tier gets you.
          </p>
          <div className="v8-tabs" role="group" aria-label="Filter titles by genre">
            {[ALL, ...genres].map((g) => (
              <button
                key={g}
                type="button"
                className={`v8-tab ${filter === g ? "is-on" : ""}`}
                aria-pressed={filter === g}
                onClick={() => setFilter(g)}
              >
                {g}
                <span className="v8-tab-n">{counts.get(g) ?? 0}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="v8-rk-grid">
        {shown.map((t) => (
          <RackCard key={t.fam} t={t} />
        ))}
      </div>

      {/* Required framing, not decoration: these are other companies' brands. */}
      <p className="v8-legal">
        Game titles, logos and key art are the trademarks and copyright of their respective owners. Nxeon rents
        the servers these titles run on and is not affiliated with, sponsored by or endorsed by any game
        studio or publisher.
      </p>
    </section>
  );
}

import type { Metadata } from "next";
import { Big_Shoulders, DM_Mono, Instrument_Sans } from "next/font/google";
import "./v8.css";

/* ===========================================================================
   v8 "Arcade" — isolated shell.

   Sits OUTSIDE the `(marketing)` route group on purpose, so it inherits none of
   the production marketing chrome — no MarketingHeader, no shared footer, no
   section primitives. Everything visual is declared in v8.css under `.v8`, so
   this concept can neither leak into nor be overridden by app/globals.css.

   TYPE — three roles, none of them the house face.

   Big Shoulders   Display voice. A tall condensed newsstand/masthead grotesque
                   with a real optical-size axis, which is why it can carry a
                   9rem headline without turning into a wall. Deliberately not
                   Inter / Geist / Space Grotesk (the generated-page tell), and
                   deliberately not a squared sci-fi face either — the failure
                   mode for a game-first page is "gamer website", and Rajdhani/
                   Orbitron-style lettering is the fastest way there. It is
                   always set MIXED CASE at 500-800 with in-line weight
                   contrast, never all-caps and never neon: that is what keeps
                   it reading as a games-press masthead rather than an esports
                   poster. The `opsz` axis is pulled in so display sizes get the
                   tighter, higher-contrast cut and small sizes get the open one.

   Instrument Sans Reading voice. Decks and prose. Slightly narrow with a bit of
                   warmth in the terminals, so paragraphs set against the
                   condensed display face look chosen rather than defaulted.

   DM Mono         Machine values ONLY — kickers, RAM/core/disk/slot figures,
                   prices, region data. The whole "premium spec sheet" register
                   of the page depends on numbers looking measured rather than
                   marketed.

   COLOUR — see v8.css. The important decision: there is no global brand accent
   at all. Chrome is warm-paper neutral and every saturated colour on the page
   is sampled out of the real key art (app/newwebsitev8/art.ts), so each title
   glows in its own game's colour instead of the whole page glowing in one.
   =========================================================================== */

const v8Display = Big_Shoulders({
  subsets: ["latin"],
  axes: ["opsz"],
  variable: "--font-v8-display",
  display: "swap",
});

const v8Text = Instrument_Sans({
  subsets: ["latin"],
  variable: "--font-v8-text",
  display: "swap",
});

const v8Mono = DM_Mono({
  subsets: ["latin"],
  weight: ["300", "400", "500"],
  variable: "--font-v8-mono",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Nxeon — game servers, online in 47 seconds",
  description:
    "Game server hosting on NVMe in Singapore and Germany. Every title gets its own machine, a 99.99% network, and full console and file access from the first minute.",
  // A bake-off concept, not a live page. Never index it.
  robots: { index: false, follow: false },
};

export default function V8Layout({ children }: { children: React.ReactNode }) {
  return (
    <div className={`v8 ${v8Display.variable} ${v8Text.variable} ${v8Mono.variable}`}>
      {children}
    </div>
  );
}

