1	"use client";
2	
3	/* ===========================================================================
4	   v8 "Arcade" — THE MARQUEE (hero).
5	
6	   A premium-storefront shelf, not a SaaS hero: the selected title's real 16:9
7	   key art fills the whole viewport behind the masthead, and a draggable rail of
8	   portrait posters runs along the bottom edge. Picking a poster swaps the
9	   backdrop, the title plate and the price — which is the moment this concept
10	   lives or dies on, so it is built to feel physical:
11	
12	   - posters tilt under the pointer with a specular sheen (useTilt)
13	   - the rail is a NATIVE overflow scroller, so touch, trackpad and keyboard all
14	     work with zero JS; mouse drag-to-scroll is layered on top as an enhancement
15	   - the active poster rises out of the rail and takes its own sampled tint
16	
17	   DRAG THRESHOLD IS 40px ON PURPOSE. A threshold under ~8px has been a real bug
18	   in this repo: ordinary clicks travel a pixel or two between pointerdown and
19	   pointerup, get classified as drags, and the click is swallowed. Nothing calls
20	   setPointerCapture until the pointer has genuinely crossed 40px either, since
21	   capturing early is what redirects the click away from the poster.
22	
23	   Backdrop images are mounted LAZILY AND KEPT: only the first title's hero is
24	   fetched on load, hovering a poster pre-fetches its hero, and anything already
25	   seen stays mounted so going back is instant. Stacking all fourteen up front
26	   would be ~1.5MB nobody asked for; fetching on click alone would make every
27	   switch flash.
28	   =========================================================================== */
29	import Image from "next/image";
30	import Link from "next/link";
31	import { useCallback, useRef, useState } from "react";
32	import { money } from "@/lib/nx/catalog";
33	import { useTilt } from "./tilt";
34	import { IconArrow, IconBolt, IconGrip } from "./icons";
35	import type { Title } from "./types";
36	
37	/** px the pointer must travel before the rail treats the gesture as a drag. */
38	const DRAG_THRESHOLD = 40;
39	/** ms after a drag ends during which a click is treated as drag fallout. */
40	const CLICK_SWALLOW_MS = 150;
41	
42	function Spec({ label, value }: { label: string; value: string }) {
43	  return (
44	    <div className="v8-spec">
45	      <span className="v8-spec-k">{label}</span>
46	      <span className="v8-spec-v">{value}</span>
47	    </div>
48	  );
49	}
50	
51	function RailPoster({
52	  title,
53	  active,
54	  onPick,
55	  onPeek,
56	}: {
57	  title: Title;
58	  active: boolean;
59	  onPick: () => void;
60	  onPeek: () => void;
61	}) {
62	  const tilt = useTilt<HTMLButtonElement>();
63	  return (
64	    <button
65	      type="button"
66	      ref={tilt.ref}
67	      onPointerMove={tilt.onPointerMove}
68	      onPointerLeave={tilt.onPointerLeave}
69	      onPointerEnter={onPeek}
70	      onFocus={onPeek}
71	      onClick={onPick}
72	      aria-pressed={active}
73	      className={`v8-rail-card v8-tilt ${active ? "is-active" : ""}`}
74	      style={{ ["--tint" as string]: title.tint }}
75	    >
76	      <span className="v8-rail-shot">
77	        {title.poster ? (
78	          <Image
79	            src={title.poster}
80	            alt=""
81	            width={300}
82	            height={450}
83	
84	            sizes="180px"
85	            draggable={false}
86	          />
87	        ) : null}
88	        <span className="v8-sheen" aria-hidden />
89	      </span>
90	      <span className="v8-rail-name">{title.name}</span>
91	      <span className="v8-rail-price">{money(title.from.priceCents)}</span>
92	    </button>
93	  );
94	}
95	
96	export default function Marquee({
97	  features,
98	  familyCount,
99	  regionLabels,
100	  entryPrice,
101	}: {
102	  features: Title[];
103	  familyCount: number;
104	  regionLabels: string[];
105	  entryPrice: string;
106	}) {
107	  const [active, setActive] = useState(0);
108	  const [seen, setSeen] = useState<Set<number>>(() => new Set([0]));
109	  const railRef = useRef<HTMLDivElement | null>(null);
110	  const drag = useRef({ down: false, moved: false, startX: 0, startScroll: 0, id: -1, endedAt: 0 });
111	
112	  const peek = useCallback((i: number) => {
113	    setSeen((prev) => (prev.has(i) ? prev : new Set(prev).add(i)));
114	  }, []);
115	
116	  const pick = useCallback(
117	    (i: number, node: HTMLElement | null) => {
118	      // A click that arrives right after a drag is that drag's fallout, not an
119	      // intent to pick. Time-based rather than a flag so a stale flag can never
120	      // swallow a real, later click.
121	      if (performance.now() - drag.current.endedAt < CLICK_SWALLOW_MS) return;
122	      setActive(i);
123	      peek(i);
124	      node?.scrollIntoView({ inline: "center", block: "nearest" });
125	    },
126	    [peek],
127	  );
128	
129	  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
130	    // Touch and pen keep the browser's own momentum scrolling — hijacking it
131	    // with scrollLeft writes is strictly worse than the native behaviour.
132	    if (e.pointerType !== "mouse" || e.button !== 0) return;
133	    const el = railRef.current;
134	    if (!el) return;
135	    drag.current = {
136	      down: true,
137	      moved: false,
138	      startX: e.clientX,
139	      startScroll: el.scrollLeft,
140	      id: e.pointerId,
141	      endedAt: 0,
142	    };
143	  };
144	
145	  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
146	    const d = drag.current;
147	    if (!d.down) return;
148	    const el = railRef.current;
149	    if (!el) return;
150	    const dx = e.clientX - d.startX;
151	    if (!d.moved) {
152	      if (Math.abs(dx) < DRAG_THRESHOLD) return;
153	      d.moved = true;
154	      // Only now — capturing before the threshold is crossed is what steals
155	      // ordinary clicks from the posters.
156	      try {
157	        el.setPointerCapture(d.id);
158	      } catch {
159	        /* capture is an enhancement; the drag still tracks without it */
160	      }
161	      el.classList.add("v8-dragging");
162	    }
163	    el.scrollLeft = d.startScroll - dx;
164	  };
165	
166	  const endDrag = () => {
167	    const d = drag.current;
168	    const el = railRef.current;
169	    if (d.moved) {
170	      d.endedAt = performance.now();
171	      if (el) {
172	        try {
173	          el.releasePointerCapture(d.id);
174	        } catch {
175	          /* already released */
176	        }
177	        el.classList.remove("v8-dragging");
178	      }
179	    }
180	    d.down = false;
181	  };
182	
183	  const hero = features[active];
184	  const slots = hero.from.slots;
185	  const term = hero.from.termMonths === 1 ? "/mo" : ` / ${hero.from.termMonths} mo`;
186	
187	  return (
188	    <section className="v8-mq" style={{ ["--tint" as string]: hero.tint, ["--tint-ink" as string]: hero.tintInk }}>
189	      {/* ---- backdrop: the selected title's real key art ------------------ */}
190	      <div className="v8-mq-art" aria-hidden>
191	        {features.map((t, i) =>
192	          seen.has(i) && t.hero ? (
193	            <Image
194	              key={t.fam}
195	              src={t.hero}
196	              alt=""
197	              fill
198	
199	              sizes="100vw"
200	              priority={i === 0}
201	              className={`v8-mq-shot ${i === active ? "is-on" : ""}`}
202	            />
203	          ) : null,
204	        )}
205	        <div className="v8-mq-scrim" />
206	        <div className="v8-mq-bloom" />
207	      </div>
208	
209	      {/* ---- top bar ------------------------------------------------------ */}
210	      <header className="v8-top">
211	        <Link href="/" className="v8-top-brand" aria-label="Nxeon home">
212	          {/* The real brand wordmark. Never re-drawn, never re-coloured. */}
213	          <Image src="/logo.png" alt="Nxeon" width={496} height={85} priority />
214	        </Link>
215	        <nav className="v8-top-nav" aria-label="Primary">
216	          <Link href="/game-servers">Game servers</Link>
217	          <Link href="/mods">Mods</Link>
218	          <Link href="/vps">VPS</Link>

