import { chromium } from "playwright";
import fs from "node:fs";

const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
fs.mkdirSync(OUT, { recursive: true });
const URL = "http://127.0.0.1:3055/newwebsitev8";
const tag = process.argv[2] ?? "a";

const b = await chromium.launch();

async function shoot(name, w, h, fn) {
  const p = await b.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const errs = [];
  p.on("console", (m) => m.type() === "error" && errs.push(m.text()));
  p.on("pageerror", (e) => errs.push("PAGEERROR " + e.message));
  await p.goto(URL, { waitUntil: "networkidle", timeout: 90000 });
  await p.waitForTimeout(1400);
  if (fn) await fn(p);
  await p.screenshot({ path: `${OUT}/${tag}-${name}.png`, fullPage: !fn });
  if (errs.length) console.log(`[${name}] console errors:`, errs.slice(0, 6));
  await p.close();
}

// Full page, desktop + mobile
await shoot("desktop-full", 1600, 1000);
await shoot("mobile-full", 390, 844);

// Viewport crops of each section on desktop
const sections = [
  ["hero", 0],
  ["rack", 1],
  ["sheet", 2],
  ["close", 3],
];
const p = await b.newPage({ viewport: { width: 1600, height: 1000 } });
await p.goto(URL, { waitUntil: "networkidle", timeout: 90000 });
await p.waitForTimeout(1500);
for (const [name, idx] of sections) {
  const sel = [".v8-mq", ".v8-rack", ".v8-sheet", ".v8-close"][idx];
  const el = await p.$(sel);
  if (!el) { console.log("missing", sel); continue; }
  await el.scrollIntoViewIfNeeded();
  await p.waitForTimeout(700);
  await p.screenshot({ path: `${OUT}/${tag}-vp-${name}.png` });
}

// Hover a rack card to capture the lift + reveal
await p.$eval(".v8-rack", (e) => e.scrollIntoView());
await p.waitForTimeout(500);
const cards = await p.$$(".v8-rk-card");
if (cards[8]) {
  const box = await cards[8].boundingBox();
  await p.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.4);
  await p.waitForTimeout(900);
  await p.screenshot({ path: `${OUT}/${tag}-hover-rack.png` });
}

// Pick a different rail poster in the hero and re-shoot
await p.evaluate(() => window.scrollTo(0, 0));
await p.waitForTimeout(500);
const rail = await p.$$(".v8-rail-card");
if (rail[4]) {
  await rail[4].hover();
  await p.waitForTimeout(400);
  await rail[4].click();
  await p.waitForTimeout(2200);
  await p.screenshot({ path: `${OUT}/${tag}-hero-picked.png` });
}

// Genre tab
await p.$eval(".v8-rack", (e) => e.scrollIntoView());
await p.waitForTimeout(400);
const tabs = await p.$$(".v8-tab");
if (tabs[4]) { await tabs[4].click(); await p.waitForTimeout(900); await p.screenshot({ path: `${OUT}/${tag}-tab-filtered.png` }); }

await p.close();
await b.close();
console.log("done ->", OUT);

