/* EVERY RESET BELOW IS WRAPPED IN :where() ON PURPOSE.

   Written the obvious way — `.v8 a { color: inherit }`, `.v8 p { margin: 0 }` —
   each of these carries specificity (0,1,1): one class plus one TYPE selector.
   That outranks every component rule in this file that is a bare single class
   (0,1,0), regardless of source order. The first render of this page proved it
   the hard way, twice over:

     - `.v8-btn-paper { color: #08080b }` lost to `.v8 a { color: inherit }`, so
       the primary CTA inherited bone on a bone background and rendered as an
       empty white box. Same for the ink and tint buttons.
     - every component `margin-top` lost to the `margin: 0` reset, which
       collapsed the page's entire vertical rhythm — headlines sat on their
       kickers, the feature list's rule ran through the paragraph above it.

   :where() contributes ZERO specificity, so these become a true floor that any
   single class can override. This is the same family of trap the repo already
   documents for `.card { position: relative }` beating Tailwind's
   `lg:absolute`; it bites just as hard inside one authored stylesheet. */
.v8 :where(h1, h2, h3, p, dl, dd, dt, ul, ol, figure) {
  margin: 0;
  padding: 0;
}

.v8 :where(ul, ol) {
  list-style: none;
}

.v8 :where(img) {
  max-width: 100%;
}

.v8 :where(a) {
  color: inherit;
  text-decoration: none;
}

.v8 :where(button) {
  font: inherit;
  color: inherit;
}

// Two nodes can share a region; the plates are per region, de-duplicated.
// Ordered by `area` so the list reads Asia then Europe — a stable rule rather
// than whatever order the node rows happened to come back in.
const regionPlates = regions
  .filter((r, i) => regions.findIndex((x) => x.label === r.label) === i)
  .sort((a, b) => a.area.localeCompare(b.area, "en") || a.label.localeCompare(b.label, "en"));

  color: var(--v8-bone);
  /* The comma's descender needs clearance from the line below it. */
  margin: 14px 0 14px;
  font-variant-numeric: lining-nums;
}

