.v8-kicker {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  row-gap: 4px;
  gap: 9px;

/* The deck sits directly on key art, and key art has bright regions (a
   Minecraft daylight sky, for one). A soft dark halo is cheaper and less
   destructive than darkening the whole scrim. */
.v8-mast .v8-deck {
  text-shadow: 0 1px 26px rgba(0, 0, 0, 0.85);
}

.v8-mast-act {
  display: flex;

/* On a phone the masthead occupies the middle of the art rather than its
   dark lower third, so the hero scrim alone is not enough. A local gradient
   under the text block keeps the top of the key art clean and still gives the
   copy a near-solid ground to sit on. */
.v8-mq-body {
  padding-top: clamp(40px, 12vh, 84px);
  background-image: linear-gradient(
    to bottom,
    rgba(8, 8, 11, 0) 0%,
    rgba(8, 8, 11, 0.5) 20%,
    rgba(8, 8, 11, 0.88) 48%,
    var(--v8-ink) 100%
  );
}

