import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
async function main() {
  const rows = await db.gamePlan.findMany({
    where: { active: true },
    select: { gameFamily: true, priceCents: true, introPriceCents: true },
  });
  const byFam = new Map<string, typeof rows>();
  for (const r of rows) {
    const l = byFam.get(r.gameFamily) ?? [];
    l.push(r);
    byFam.set(r.gameFamily, l);
  }
  const cheap = [...byFam.entries()].map(
    ([f, l]) => [f, l.reduce((a, b) => (b.priceCents < a.priceCents ? b : a))] as const,
  );
  const mins = cheap.map(([, r]) => r.priceCents);
  console.log("families:", byFam.size, "rows:", rows.length);
  console.log("min cheapest:", Math.min(...mins), "max cheapest:", Math.max(...mins));
  for (const f of ["factorio", "gmod", "corekeeper", "bedrock", "squad", "satisfactory", "minecraft"]) {
    const r = cheap.find(([x]) => x === f);
    console.log(" ", f, JSON.stringify(r?.[1]));
  }
  const plans = await db.plan.findMany({ where: { active: true }, select: { slug: true, priceCents: true } });
  console.log("VPS:", JSON.stringify(plans));
  await db.$disconnect();
}
main();

